CREATE OR REPLACE FUNCTION pos.decode_money_components_wire()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_marker constant text := '__BALAM_MONEY_V1__';
  v_payload jsonb;
begin
  if new.metodo is not null and left(new.metodo, char_length(v_marker)) = v_marker then
    begin
      v_payload := substring(new.metodo from char_length(v_marker) + 1)::jsonb;
    exception when others then
      raise exception 'invalid_money_components_wire' using errcode = '22023';
    end;
    new.metodo := nullif(trim(v_payload ->> 'nominalMethod'), '');
    new.components := v_payload -> 'components';
    if new.metodo is null or not pos.money_components_valid(new.components,
        coalesce((to_jsonb(new) ->> 'monto')::numeric, (to_jsonb(new) ->> 'total')::numeric)) then
      raise exception 'invalid_money_components' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.guard_device_recovery_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
declare j jsonb; d text;
 h jsonb := coalesce(nullif(current_setting('request.headers',true),'')::jsonb,'{}');
begin
 if TG_OP='DELETE' then j:=to_jsonb(OLD); else j:=to_jsonb(NEW); end if;
 -- A stored origin is not the identity of a later financial transaction.
 d:=h->>'x-balam-device-id';
 if coalesce(current_setting('pos.h149_rpc',true),'')<>'on' and d is null then
  d:=coalesce(j->>'sync_device_id',j->>'device_id');
 end if;
 perform pos.assert_device_recovery_write(d,array[j->>'operation_id',j->>'commit_id']);
 if TG_OP='DELETE' then return OLD; end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION pos.guard_entity_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare op text;
begin
  if pos.h133_internal_enabled() and tg_table_name='products' then return new; end if;
  if tg_op='INSERT' then
    new.sync_version:=1; new.sync_base_version:=null; new.updated_at:=now(); return new;
  end if;
  op:=case when new.deleted_at is not null and old.deleted_at is null then 'delete' else 'upsert' end;
  if new.sync_base_version is not null and new.sync_base_version<>old.sync_version then
    insert into pos.sync_conflicts(entity,entity_id,operation,expected_version,actual_version,
      attempted,current_row,device_id)
    values(tg_table_name,old.id,op,new.sync_base_version,old.sync_version,
      to_jsonb(new)-'sync_base_version',to_jsonb(old),new.sync_device_id);
    return old;
  end if;
  new.sync_version:=old.sync_version+1; new.sync_base_version:=null; new.updated_at:=now(); return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.guard_online_commercial_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pos', 'auth'
AS $function$
begin
 if (select enabled from pos.online_runtime where singleton) and not pos.online_request_context()
    and not(auth.uid() is null and ((session_user in('postgres','service_role','supabase_admin')
      and coalesce(current_setting('role',true),'none') not in('anon','authenticated'))
     or (coalesce(auth.jwt()->>'role','')='service_role' and current_setting('role',true)='service_role'))) then
  raise exception using errcode='42501',message='ONLINE_COMMAND_REQUIRED';
 end if;
 if TG_OP='DELETE' then return OLD; end if;
 return NEW;
end $function$

CREATE OR REPLACE FUNCTION pos.h101_ensure_reference_family()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if new.record_model = 'v2' and new.reference_family_id is null then
    new.reference_family_id := gen_random_uuid();
  elsif new.record_model = 'v1' then
    new.reference_family_id := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_alias_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if pos.h133_internal_enabled() then return case when tg_op='DELETE' then old else new end; end if;
  raise exception 'BARCODE_ALIAS_IMMUTABLE';
end;
$function$

CREATE OR REPLACE FUNCTION pos.h133_guard_operational_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_enforced boolean;
begin
  if pos.h133_internal_enabled() then return new; end if;
  select enforced into v_enforced from pos.inventory_contract_state where singleton;
  if not coalesce(v_enforced,false) then return new; end if;
  if new.deleted_at is null and new.record_model='v1' then raise exception 'V1_OPERATIONAL_FORBIDDEN'; end if;
  if new.deleted_at is null and new.record_model='v2' then
    if new.barcode_contract is distinct from 3 or new.barcode_code is distinct from pos.h133_barcode_v3_from_id(new.id)
       or jsonb_typeof(new.barcode_aliases)<>'array' then
      raise exception 'BARCODE_CONTRACT_V3_REQUIRED';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.h94_sync_v2_stock_shape()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare v_from_legacy integer;
begin
  if new.record_model <> 'v2' then return new; end if;
  if tg_op = 'UPDATE' and new.stock is distinct from old.stock
     and new.stock_quantity is not distinct from old.stock_quantity then
    select coalesce(sum(greatest(0, coalesce((entry ->> 'stock')::integer, 0))), 0)::integer
      into v_from_legacy
      from jsonb_array_elements(coalesce(new.stock, '[]'::jsonb)) entry
     where entry ->> 'talla' = new.size_code;
    new.stock_quantity := v_from_legacy;
  end if;
  new.stock_quantity := greatest(0, coalesce(new.stock_quantity, 0));
  new.physical_identity_locked := case when tg_op = 'INSERT'
    then coalesce(new.physical_identity_locked, false) or new.stock_quantity > 0
    else coalesce(old.physical_identity_locked, false)
      or coalesce(new.physical_identity_locked, false) or new.stock_quantity > 0 end;
  new.ornament_color_codes := coalesce(new.ornament_color_codes, '[]'::jsonb);
  new.stock := jsonb_build_array(jsonb_build_object(
    'talla', new.size_code, 'escala', coalesce(new.size_scale, ''),
    'stock', new.stock_quantity
  ));
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.protect_sync_device_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pos'
AS $function$
begin
 if current_user not in ('postgres','service_role') and (
   (old.status='revoked' and new.status is distinct from old.status)
   or (new.status='revoked' and old.status is distinct from new.status)
   or (new.metadata - array['last_heartbeat_error']) is distinct from (old.metadata - array['last_heartbeat_error'])
 ) then raise exception using errcode='42501',message='La administración del equipo requiere el Centro de equipos.'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION pos.reject_purged_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
declare
  v_kind text := tg_argv[0];
  v_identity text;
begin
  if v_kind = 'sale' then v_identity := new.operation_id;
  else v_identity := new.id;
  end if;
  if nullif(trim(coalesce(v_identity, '')), '') is null then
    return new;
  end if;
  if exists (
    select 1 from pos.purged_documents t
     where t.kind = v_kind and t.identity = v_identity
  ) then
    raise exception 'operation_purged'
      using errcode = 'P0001',
            detail = format('%s %s fue eliminado por una limpieza de datos de prueba', v_kind, v_identity),
            hint = 'Ese documento ya no existe: la terminal debe descartar la operacion pendiente';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.require_sale_stock_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  -- Apartados y cancelaciones no retiran inventario todavía.
  if new.estado in ('Apartado', 'Cancelado') then
    return new;
  end if;

  -- Una venta histórica ya existente sin operation_id continúa actualizable.
  if tg_op = 'UPDATE'
     and old.operation_id is null
     and new.operation_id is null then
    return new;
  end if;

  if nullif(trim(new.operation_id), '') is null
     or not exists (
       select 1
         from pos.stock_reservations r
        where r.operation_id = new.operation_id
          and r.folio = new.folio
     ) then
    raise exception 'La venta no tiene una reserva de inventario confirmada'
      using errcode = 'P0001',
            hint = 'Ejecute pos.reserve_sale_stock antes de guardar la venta';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION pos.restrict_direct_commission_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pos', 'pg_temp'
AS $function$
begin
  if current_user in ('authenticated', 'anon')
     and (
       new.comision_acum is distinct from old.comision_acum
       or new.ventas_mes is distinct from old.ventas_mes
       or new.ventas_num is distinct from old.ventas_num
     ) then
    raise exception 'COMMISSION_RPC_REQUIRED' using errcode = '42501';
  end if;
  return new;
end;
$function$
